#include <iostream>
class Base {
public:
    int a;
};
class Derived : public Base {
public:
    int b;
};
int main() {
    int Base::* ptrBase = &Base::a; // pointer to member of Base
    int Derived::* ptrDerived = &Derived::b; // pointer to member of Derived
    // Combining cv-qualifiers: const and volatile qualifiers are merged when assigning or comparing
    const int Base::* constPtrBase = &Base::a;
    volatile int Derived::* volatilePtrDerived = &Derived::b;
    // Demonstrating cv-qualification merging in context of inheritance
    return 0;
}
